public with sharing class ContactDomainService {

    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> result = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email != null
        ];

        for (Contact c : contacts) {
            String domain = c.Email.toLowerCase().split('@')[1];
            if (!result.containsKey(domain)) {
                result.put(domain, new List<Contact>());
            }
            result.get(domain).add(c);
        }

        return result;
    }
}
