public class ContactLookupAction {

    public class Request {
        @InvocableVariable(label='Email' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact ID')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // Collect unique, normalized emails from valid requests
        Set<String> uniqueEmails = new Set<String>();
        for (Request req : requests) {
            if (req != null && req.email != null) {
                String trimmed = req.email.trim();
                if (trimmed != '') {
                    uniqueEmails.add(trimmed.toLowerCase());
                }
            }
        }

        // Single SOQL query to find contacts matching any of the unique emails
        Map<String, Contact> emailToContact = new Map<String, Contact>();
        if (!uniqueEmails.isEmpty()) {
            List<Contact> contacts = [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :uniqueEmails
                ORDER BY CreatedDate ASC
            ];

            for (Contact c : contacts) {
                String key = c.Email.toLowerCase();
                if (!emailToContact.containsKey(key)) {
                    emailToContact.put(key, c);
                }
            }
        }

        // Build results in the same order as requests
        for (Request req : requests) {
            Result result = new Result();
            if (req != null && req.email != null) {
                String trimmed = req.email.trim();
                if (trimmed != '' && emailToContact.containsKey(trimmed.toLowerCase())) {
                    Contact matched = emailToContact.get(trimmed.toLowerCase());
                    result.contactId = matched.Id;
                    result.found = true;
                } else {
                    result.contactId = null;
                    result.found = false;
                }
            } else {
                result.contactId = null;
                result.found = false;
            }
            results.add(result);
        }

        return results;
    }
}
