public with sharing class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();
        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        Date today = Date.today();
        Date startOfYear = Date.newInstance(today.year(), 1, 1);
        Date startOfNextYear = startOfYear.addYears(1);

        AggregateResult[] aggregates = [
            SELECT AccountId accId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsWon = true
              AND CloseDate >= :startOfYear
              AND CloseDate < :startOfNextYear
            GROUP BY AccountId
        ];

        for (AggregateResult ar : aggregates) {
            Id accId = (Id) ar.get('accId');
            Decimal total = (Decimal) ar.get('totalAmount');
            result.put(accId, total != null ? total : 0);
        }

        for (Id accId : accountIds) {
            if (!result.containsKey(accId)) {
                result.put(accId, 0);
            }
        }

        return result;
    }
}
