public without sharing class LineItemDiscountHandler {

    /**
     * Sets a null Discount on each incoming line to its product's standard
     * discount, obtained via PricingRules. Lines that already have a
     * Discount (including 0) are left untouched.
     *
     * Results are cached per unique Product2Id inside a single pass so that
     * PricingRules.standardDiscountFor is invoked at most once per product,
     * keeping the per-transaction SOQL count well under the governor limit
     * even for CPQ imports of up to 200 lines.
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> lines) {
        if (lines == null || lines.isEmpty()) {
            return;
        }

        Map<Id, Decimal> standardDiscountByProduct = new Map<Id, Decimal>();

        for (OpportunityLineItem line : lines) {
            if (line.Discount == null && String.isNotBlank(line.Product2Id)) {
                if (!standardDiscountByProduct.containsKey(line.Product2Id)) {
                    standardDiscountByProduct.put(
                        line.Product2Id,
                        PricingRules.standardDiscountFor(line.Product2Id)
                    );
                }
                line.Discount = standardDiscountByProduct.get(line.Product2Id);
            }
        }
    }
}
