trigger CaseTrigger on Case (after update) {

    // Collect all cases that just transitioned from open → closed and have a contact.
    // We enqueue a single Queueable job (rather than one per case) so that bulk
    // closes — e.g. agents closing 200 cases via list view / nightly API cleanup —
    // don't exceed the per-transaction limit of 50 queueable jobs.
    List<Id> newlyClosedCaseIds = new List<Id>();

    for (Case c : Trigger.new) {
        Case oldCase = Trigger.oldMap.get(c.Id);
        if (c.IsClosed && !oldCase.IsClosed && c.ContactId != null) {
            newlyClosedCaseIds.add(c.Id);
        }
    }

