        if (result === true) {
            try {
                await deleteRecord(row.Id);
                this._tableData = this._tableData.filter(item => item.Id !== row.Id);
                this.dispatchEvent(new ShowToastEvent({
                    title: 'Opportunity deleted',
                    variant: 'success'
