```apex
public class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();
        Date today = Date.today();

        // SOQL #1: Load all current primary affiliations for affected contacts
        Map<Id, List<npe5__Affiliation__c>> contactToCurrentPrimary = new Map<Id, List<npe5__Affiliation__c>>();
        for (npe5__Affiliation__c aff : [
            SELECT Id, npe5__Contact__c, npe5__Organization__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
              AND npe5__Primary__c = true
              AND npe5__Status__c = 'Current'
        ]) {
            if (!contactToCurrentPrimary.containsKey(aff.npe5__Contact__c)) {
                contactToCurrentPrimary.put(aff.npe5__Contact__c, new List<npe5__Affiliation__c>());
            }
            contactToCurrentPrimary.get(aff.npe5__Contact__c).add(aff);
        }

        List<npe5__Affiliation__c> affiliationsToInsert = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> affiliationsToUpdate = new List<npe5__Affiliation__c>();

        for (Id contactId : contactIds) {
            Id newOrgId = employerByContactId.get(contactId);
            List<npe5__Affiliation__c> currentPrimary = contactToCurrentPrimary.get(contactId);

            // Skip if contact is already primarily affiliated to this organization
            Boolean alreadyPrimaryToTarget = false;
            if (currentPrimary != null) {
                for (npe5__Affiliation__c aff : currentPrimary) {
                    if (aff.npe5__Organization__c == newOrgId) {
                        alreadyPrimaryToTarget = true;
                        break;
                    }
                }
            }
            if (alreadyPrimaryToTarget) {
                continue;
            }

            // Demote existing primary affiliations to Former
            if (currentPrimary != null) {
                for (npe5__Affiliation__c aff : currentPrimary) {
                    aff.npe5__Status__c = 'Former';
                    aff.npe5__EndDate__c = today;
                    aff.npe5__Primary__c = false;
                    affiliationsToUpdate.add(aff);
                }
            }

            // Create new Current, primary affiliation
            affiliationsToInsert.add(new npe5__Affiliation__c(
                npe5__Contact__c = contactId,
                npe5__Organization__c = newOrgId,
                npe5__Status__c = 'Current',
                npe5__Primary__c = true,
                npe5__StartDate__c = today,
                npe5__Role__c = 'Current'
            ));
        }

        // DML #1: Insert new primary affiliations (NPSP syncs Contact.npsp__Primary_Affiliation__c)
        if (!affiliationsToInsert.isEmpty()) {
            Database.insert(affiliationsToInsert, false);
        }

        // DML #2: Demote previous primary affiliations to Former
        if (!affiliationsToUpdate.isEmpty()) {
            Database.update(affiliationsToUpdate, false);
        }
    }
}
