global class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    global override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newList,
        List<SObject> oldList,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {

        List<Task> tasksToInsert = new List<Task>();

        for (Integer i = 0; i < newList.size(); i++) {
            Opportunity opp = (Opportunity) newList[i];

            if (opp.IsClosed && opp.Amount != null && opp.Amount >= 5000) {

                Boolean alreadyQualified = false;

                if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
                    Opportunity oldOpp = (i < oldList.size()) ? (Opportunity) oldList[i] : null;
                    if (oldOpp != null
                            && oldOpp.IsClosed
                            && oldOpp.Amount != null
                            && oldOpp.Amount >= 5000) {
                        alreadyQualified = true;
                    }
                }

                if (!alreadyQualified) {
                    tasksToInsert.add(buildTask(opp));
                }
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return null;
    }

    private Task buildTask(Opportunity opp) {
        Task t = new Task();
        t.Subject = 'Major gift thank-you call';
        t.Priority = 'High';
        t.Status = 'Not Started';
        t.WhatId = opp.Id;
        t.WhoId = opp.npsp__Primary_Contact__c;
        t.OwnerId = opp.OwnerId;
        t.ActivityDate = opp.CloseDate.addDays(3);
        return t;
    }
}
