public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    private static Set<Id> processedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Task> tasksToInsert = new List<Task>();
        Map<Id, SObject> oldMap = new Map<Id, SObject>();

        for (SObject oldOpp : triggerOld) {
            oldMap.put((Id) oldOpp.get('Id'), oldOpp);
        }

        for (SObject newOpp : triggerNew) {
            Id oppId = (Id) newOpp.get('Id');
            if (!processedOpportunityIds.contains(oppId)) {
                processedOpportunityIds.add(oppId);

                SObject oldOpp = oldMap.get(oppId);
                if (oldOpp != null) {
                    Decimal newAmount = (Decimal) newOpp.get('Amount');
                    Decimal oldAmount = (Decimal) oldOpp.get('Amount');

                    if (newAmount != oldAmount) {
                        tasksToInsert.add(new Task(
                            Subject  = 'Amount changed',
                            WhatId   = oppId,
                            Status   = 'Completed'
                        ));
                    }
                }
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
